<template><view class="page"><view class="wrap"><MobileHeader title="文件" back-icon-name="chevron-left"/><view class="card upload-card"><view class="file-icon"><AppIcon name="apps" :size="36" color="#294fdb"/></view><text class="section-title">上传文件</text><button class="primary" :disabled="busy" @tap="choose">{{busy?'正在上传…':'选择文件'}}</button></view><view v-if="url" class="card"><view class="row"><text>{{name}}</text><text class="badge">上传成功</text></view><text class="file-url" selectable>{{url}}</text><button class="primary" @tap="download">下载文件</button></view><text class="error">{{error}}</text></view></view></template><script setup lang="ts">import {ref} from 'vue';import MobileHeader from '@/components/MobileHeader.vue';import AppIcon from '@/components/AppIcon.vue';import {client,requireSession} from '@/platform';import {chooseDocument} from '@/services/document-upload';const url=ref(''),name=ref(''),busy=ref(false),error=ref('');async function upload(path:unknown,fileName:string){busy.value=true;error.value='';try{url.value=await client.upload(path);name.value=fileName;}catch{error.value='文件上传失败，请重试';}finally{busy.value=false;}}function choose(){if(!requireSession()||busy.value)return;
// #ifdef H5
uni.chooseFile({count:1,success:r=>{const file=(Array.isArray(r.tempFiles)?r.tempFiles[0]:r.tempFiles) as {path:string;name?:string};void upload(file.path,file.name||'文件');}});
// #endif
// #ifdef APP-PLUS
void chooseDocument().then(file=>{if(file)return upload(file,file.name);}).catch(()=>{error.value='文档选择失败，请选择不超过 8 MiB 的本机文件';});
// #endif
}function download(){
// #ifdef H5
if(typeof document!=='undefined'){const a=document.createElement('a');a.href=url.value;a.download=name.value;a.rel='noopener';a.click();return;}
// #endif
// #ifdef APP-PLUS
if(typeof plus!=='undefined')plus.runtime.openURL(url.value,()=>uni.showToast({title:'下载链接无法打开',icon:'none'}));
// #endif}</script><style scoped lang="scss">.page{min-height:100vh;background:#f7f8fc;padding-bottom:calc(110px + env(safe-area-inset-bottom))}.wrap{max-width:500px;margin:auto;padding:0 15px}.section-title{font-size:17px;font-weight:600}.card{background:#fff;border-radius:18px;padding:18px;margin-top:14px;box-shadow:0 6px 16px rgba(20,31,51,.06)}.row{display:flex;align-items:center;justify-content:space-between;gap:14px;padding:14px 0;border-bottom:1px solid #eef1f6}.row:last-child{border:0}.muted{color:#8791a4;font-size:12px}.primary{margin-top:20px;background:#294fdb;color:white;border-radius:12px;font-size:14px}.field{padding:15px 0;border-bottom:1px solid #eef1f6}.field text{display:block;font-size:13px;color:#636e82;margin-bottom:10px}.field input{font-size:14px}.empty{padding:36px 0;text-align:center;color:#8791a4;font-size:14px}.badge{color:#294fdb;font-size:12px}.error{color:#d44545;font-size:13px;margin-top:12px}</style><style scoped>.upload-card{text-align:center;padding:32px 20px}.upload-card>.section-title{display:block;margin-top:18px}.file-icon{width:72px;height:72px;display:flex;align-items:center;justify-content:center;margin:auto;border-radius:23px;background:#edf1ff}.file-url{display:block;font-size:12px;line-height:1.7;color:#636e82;word-break:break-all}</style>
